{
  "spells": [
    {
      "id": "spell_water_13",
      "theory": "流幕术以魔力牵引水体沿预设的引力线向上抽引，使水在通道断面展开为连续水帘。帘幕依靠水的表面张力与持续魔力维持，不能凭空造水，必须从附近水源或容器中汲取。水声源于帘幕落地与内部回流，因此施法位置会随水声暴露。水帘能遮挡视线与飞尘，但无法阻挡刀剑或重物穿越。",
      "casting": "以手掌朝向水面，缓慢抬腕引导水线上升，另一手在水帘高度处画横向符文固定帘幕边缘。",
      "failure": "水面只隆起短暂水柱便回落，地面留下大片湿痕。若符文横向歪斜，帘幕会偏向一侧，形成半透明水幕，水声忽大忽小，反而暴露施法者方位。",
      "counters": [
        "向水帘投掷干沙或灰烬，颗粒破坏表面张力使帘幕破裂。",
        "在帘幕边缘施放反向气流，干扰引力线令水幕提前坠落。"
      ],
      "socialConsequences": "河谷乡约允许用流幕遮住渡口视线，但要求施法者事先告知对岸船夫，免得水声引发误会。城市公会按许可登记，私自在水道设幕可能被视作妨碍通行。琥珀海岸港务规定，若水帘令装卸工滑倒或货物受潮，施法者须赔偿货损。竞争者常指责水帘抢走遮蔽生意，但多数人承认它比搬动布幔省力。",
      "law": {
        "river": "consent",
        "city": "permit",
        "port": "permit"
      },
      "proficiencyEffects": [
        "初学时水帘边缘散碎，水声杂乱，只能勉强遮住半人高的视线。",
        "熟练后帘幕宽度稳定，水声均匀，可完整掩住一处窄道入口。",
        "能控制帘幕厚度，减少溅水，使地面湿痕范围缩小。",
        "极熟练者可在水帘落下前预判回流方向，水声更集中，不易暴露位置。"
      ]
    },
    {
      "id": "spell_water_14",
      "theory": "潮压阵在已有水体的狭小区域内制造均匀水压，使站在其中的目标承受来自四面八方的挤迫。魔力通过水体传导，压力随水深增加，因此浅水区效果较弱。阵形需要至少三处锚点固定压力方向，锚点可设在池壁、船板或石缝。压力不会直接撕裂皮肉，但会压迫呼吸与行动，使人难以站稳或举臂。",
      "casting": "以足尖在水面画出三角锚点，依次向每个锚点注入魔力，待水面出现均匀波纹后双手下压。",
      "failure": "锚点未成三角时，压力只从一侧涌来，目标被推倒而非受困。若魔力注入过快，水面会炸开，施法者自身也被反冲水压推倒，衣物尽湿。",
      "counters": [
        "破坏任一锚点符文，压力场会因失衡而迅速消散。",
        "向水中投入大量碎石，扰乱水体传导，使压力分布不均。"
      ],
      "socialConsequences": "河谷乡约严禁在公共水井或饮水渠中布设潮压阵，因为压力会搅浑水源并惊吓取水者。城市公会要求施法者取得水域管理者的许可，且不得在码头泊位内使用，以免挤坏船板。琥珀海岸港务将潮压阵列为高风险作业，若造成船员受伤或货物挤压，须按航运事故追究责任。渔民与装卸工对此术态度矛盾，既怕它伤人，又承认它能驱赶水中的危险生物。",
      "law": {
        "river": "crime",
        "city": "permit",
        "port": "permit"
      },
      "proficiencyEffects": [
        "初学时压力时断时续，目标只需弯腰即可脱离影响范围。",
        "熟练后压力均匀，可让站在浅水中的目标难以迈步。",
        "能精确控制压力上限，避免对目标造成骨折等严重伤害。",
        "极熟练者可在狭小水域内维持稳定压力，同时减少对外围水体的扰动。"
      ]
    }
  ]
}
